  'settings.streamFormat.hlsShort': 'HLS (.m3u8) · ổn định',
  'settings.streamFormat.tsShort': 'MPEG-TS (.ts) · nhanh',
  'settings.streamFormat.autoShort': 'Tự động · @fmt',
  'settings.streamFormat.autoTitle': 'Tự động (được khuyến nghị)',
